function e(e){return Math.PI*(e/20)**2}function t(t,n=.4){return e(t*n)}function n(e,t){return e*t*10}function r(e,t){return e*1e3/t/100/60}function i(e,t){return e*t/600}function a(e,t){return 120*e/t}function o(e,t=.04){return e*(1-t)}function s(e){return Number(((e%360+360)%360).toFixed(1))}function c(e,t,n=1){return s(e*t*n)}function l(e,t=1){return(e*t%4+4)%4}function u(e){return 1e3/Math.max(.1,e)}export{t as a,l as c,e as i,u as l,i as n,o,r,c as s,n as t,a as u};